div.script:
// Set header height
var _mh = document.querySelector('header.m-header__mobile');
var _dh = document.querySelector('header.m-header__desktop');

function _shh() {
  if (!_mh || !_dh) {
    _mh = document.querySelector('header.m-header__mobile');
    _dh = document.querySelector('header.m-header__desktop');
  }
  // Header
  var _hd = window.innerWidth < 1024 ? _mh : _dh;
  if (_hd) {
    document.documentElement.style.setProperty('--m-header-height', _hd.offsetHeight + 'px');
    window.MinimogSettings.headerHeight = _hd.offsetHeight;
  }
}
// setTopbarHeight
function _stbh() {
  // Topbar
  var _tb = document.querySelector('.m-topbar');
  if (_tb) {
    document.documentElement.style.setProperty('--m-topbar-height', _tb.offsetHeight + 'px');
    window.MinimogSettings.topbarHeight = _tb.offsetHeight;
  }
}

// setAnnouncementbarHeight
function _sabh() {
  var _ab = document.querySelector('m-announcement-bar');
  if (_ab) {
    document.documentElement.style.setProperty('--m-announcement-height', _ab.offsetHeight + 'px');
    window.MinimogSettings.topbarHeight = _ab.offsetHeight;
  }
}

// Calc all height
function _calcHeights() {
  _stbh();
  _shh();
  _sabh();
}
_calcHeights();
document.addEventListener('matchTablet', () => {
  _calcHeights();
});
document.addEventListener('unmatchTablet', () => {
  _calcHeights();
});

if (Shopify.designMode) {
  document.addEventListener('shopify:section:load', function (event) {
    const header = document.querySelector('m-header');
    if (typeof Megamenu !== 'undefined' && header) {
      const megaMenu = new Megamenu(header);
    }
  });
}

body.script:
window.addEventListener('load', function () {
  window.__sfWindowLoaded = true;
});

var fader = document.querySelector('.m-page-transition');
function __fadeInPage() {
  if (!window.AnimationEvent || !fader) return;

  let ignore_beforeunload = false;

  document.querySelectorAll('a[href^=mailto], a[href^=tel]').forEach((link) => {
    link.addEventListener('click', () => {
      ignore_beforeunload = true;
    });
  });

  // Page transition
  window.addEventListener('beforeunload', () => {
    if (!ignore_beforeunload) fader.classList.add('fade-in');
  });
  window.addEventListener('DOMContentLoaded', () => {
    document.documentElement.classList.remove('m:overflow-hidden');
    document.body.classList.remove('m:overflow-hidden');

    // fader.classList.remove('fade-in')
    setTimeout(() => {
      fader.classList.add('fade-out');
    }, 300);

    document.dispatchEvent(new CustomEvent('page:loaded'));
  });
  window.addEventListener('pageshow', (event) => {
    // Removes unload class when returning to page via history
    if (event.persisted) {
      fader.classList.remove('fade-in');
      // fader.classList.add('fade-out')
    }
  });
}
__fadeInPage();

// Lazyload background image
function addIntersectionObserver(classSelector, newClass = '') {
  let lazyImages = [].slice.call(document.getElementsByClassName(classSelector));
  if ('IntersectionObserver' in window) {
    let lazyImageObserver = new IntersectionObserver(function (entries, observer) {
      entries.forEach(function (entry) {
        if (entry.isIntersecting) {
          let lazyImage = entry.target;
          lazyImage.classList.remove(classSelector);
          newClass && lazyImage.classList.remove(newClass);
          lazyImageObserver.unobserve(lazyImage);
        }
      });
    });

    lazyImages.forEach(function (lazyImage) {
      lazyImageObserver.observe(lazyImage);
    });
  }
}
function handleBackgroundImageLazyload() {
  return addIntersectionObserver('m-bg-lazy');
}

handleBackgroundImageLazyload();
document.addEventListener('shopify:section:load', () => {
  handleBackgroundImageLazyload();
});

// Init scroll top
function __scrollToTop(element, callback) {
  if (!element) element = document.querySelector('#scroll-to-top-target');
  element.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
  if (callback) callback();
}

function __initScrollTop() {
  const scrollTopButton = document.querySelector('#scroll-to-top-button');
  if (scrollTopButton) {
    scrollTopButton.addEventListener('click', () => __scrollToTop());
    window.addEventListener('scroll', function () {
      const method = window.scrollY > 100 ? 'add' : 'remove';
      scrollTopButton.classList[method]('is-show');
    });
  }
}

// Init terms checkbox
function __initTermsCheckbox() {
  addEventDelegate({
    selector: '.m-terms-conditons [name="agree_terms"]',
    event: 'change',
    handler: (e, target) => {
      let button = target.closest('.m-terms-conditons').nextElementSibling;
      while (button) {
        if (button.hasAttribute('data-terms-action')) {
          break;
        }

        button = button.nextElementSibling;
      }
      if (button && button.hasAttributes('data-terms-action')) {
        if (target.checked) {
          button.removeAttribute('disabled');
        } else {
          button.setAttribute('disabled', true);
        }
      }
    },
  });
}

window.addEventListener('load', () => {
  __initScrollTop();
  __initTermsCheckbox();
});

document.addEventListener('DOMContentLoaded', function () {
  // 소셜 아이콘 링크 접근성 이름
  [['instagram','Instagram'],['tiktok','TikTok'],['pinterest','Pinterest']].forEach(function (p) {
    document.querySelectorAll('a.m-icon-box__icon[href*="'+p[0]+'"]').forEach(function (a) {
      if (!a.getAttribute('aria-label')) a.setAttribute('aria-label', 'Round Lab on ' + p[1]);
    });
  });
  // 빈 어나운스먼트 바 링크 이름 부여
  document.querySelectorAll('a.m-announcement-bar__link').forEach(function (a) {
    if (!a.textContent.trim() && !a.getAttribute('aria-label')) {
      var slug = (a.getAttribute('href') || '').split('/').filter(Boolean).pop() || 'announcement';
      a.setAttribute('aria-label', slug.replace(/-/g, ' '));
    }
  });
});

