const nvdShop = 'hello-3c71.myshopify.com';
const nvdShopCurrency = '${{amount}}';
const nvdControls = {
	subtotal_item: '.m-cart__subtotal--price,.rebuy-cart__flyout-subtotal-amount',
	CheckoutBtns: '[name="checkout"],[name="checkout"] *,.rebuy-cart__checkout-button,.rebuy-cart__checkout-button *',
	clickTriggers: '.reelUp_popup_cart_product_quantity_button,.reelUp_popup_cart_product_quantity_button *,.reelUp_popup_cart_delete_button,.reelUp_popup_cart_delete_button *,.reelUp_modal_atc_btn,.reelUp_modal_atc_btn *,.reelUp_modal_cart_btn,.reelUp_modal_cart_btn *,.m-quantity__button,.m-quantity__button *,[href="/cart"],[href="/cart"] *,.rebuy-cart__flyout-item-quantity-widget-button,.rebuy-cart__flyout-item-quantity-widget-button *,.rebuy-cart__flyout-item-remove,.rebuy-cart__flyout-item-remove *', 
	changeTrigger: '.m-quantity__input',
	cursorControl: '.nvd-mini',
	showConsoleMessage: false,
	iosDeviceListener:'click',
	trackWidget: false,
	forceClick: true,
	forceCheckout: true,
	redirectCheckout: {
		upsaleOff: true,
		noProtection: false
	},
nvdInject:{
