    booster: {
        js: ["https://cdn.shopify.com/extensions/019fd550-0f65-7724-a137-e558cdf94a67/freegifts-213/assets/booster.min.js"],
        css: ["https://cdn.shopify.com/extensions/019fd550-0f65-7724-a137-e558cdf94a67/freegifts-213/assets/bogos.booster.min.css"]
    }
}

let appstleCount = 0
function isAppstleJSInitiated() {
   appstleCount++;
   if (window?.["RSConfig"] || appstleCount > 20) {
       let appstleStyleElement = document.querySelector('#appstle-payment-button-override');
       if (appstleStyleElement) {
           appstleStyleElement.remove();
       }
   } else {
       setTimeout(isAppstleJSInitiated, 500)
   }
}
isAppstleJSInitiated();

function pollAppstleInit() {
    if (window?.appstleInit) {
    window?.appstleInit()
    } else {
    setTimeout(pollAppstleInit, 30);
    }
}

(function() {
  const ready = (callback) => {
    if (document.readyState !== 'loading') callback();
    else document.addEventListener('DOMContentLoaded', callback);
  }

  const updateAndOpenDawnCart = () => {
    fetch("/cart/update.js", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        updates: {},
        sections: ["cart-drawer", "cart-icon-bubble"],
      }),
    })
      .then((res) => res.json())
      .then((cartData) => {
        document.querySelector("cart-drawer")?.renderContents(cartData);
        document.querySelector("cart-drawer.drawer")?.classList?.remove("is-empty");
      });
  };

  const openCartDrawer = async (cart_type) => {
    if (cart_type === "1") {
      // Dawn theme
      updateAndOpenDawnCart();
    } else if (cart_type === "2") {
      // Impact theme
      document?.documentElement?.dispatchEvent(new CustomEvent('cart:refresh', {
        bubbles: true
      }));
      document?.documentElement?.dispatchEvent(new CustomEvent('variant:add', {
        bubbles: true
      }));
    } else if (cart_type === "3") {
      // Focal theme
      document?.querySelector('[aria-controls="mini-cart"]')?.click();
    } else if (cart_type === "4") {
      // Split theme
      document?.querySelector('[aria-controls="cart-drawer"]')?.click();
    } else if (cart_type === "5" && window?.corner?.do) {
      // Corner Cart app
      window.corner.do("refreshCart");
      window.corner.do("openCart");
    } else if (cart_type === "6") {
      // Concept theme
      document.querySelector('[aria-controls="CartDrawer"]').click();
    } else if (cart_type === "7") {
      // Enterprise theme
      document?.documentElement?.dispatchEvent(new CustomEvent('dispatch:cart-drawer:refresh', {
        bubbles: true
      }));
      document?.documentElement?.dispatchEvent(new CustomEvent('dispatch:cart-drawer:open', {
        bubbles: true
      }));
    } else if (cart_type === "8") {
      // Shine theme
      window?.SHTHelper?.forceUpdateCartStatus()
      window?.shtCartDrawer?.openDrawer();
    } else if (cart_type === "9") {
      // Sahara theme
      document?.querySelector('a[data-cart-link]')?.click();
    } else if (cart_type === "10") {
      // Refresh theme
      updateAndOpenDawnCart();
    } else if (cart_type === "11") {
      // Flow theme
      document.querySelector('[aria-controls="CartDrawer"]').click();
    } else if (cart_type === "12") {
      // Combine theme
      document.querySelector('a[href="/cart"]').click();
    } else if (cart_type === "13") {
      // AMP Slide Cart
      window?.SLIDECART_UPDATE?.(() => {
        window?.SLIDECART_OPEN?.();
      });
    } else if (cart_type === "14") {
      // Eurus theme
      window?.Alpine?.store('xMiniCart')?.reLoad();
      window?.Alpine?.store('xMiniCart')?.openCart();
    } else if (cart_type === "15") {
      // Expanse theme
      document?.documentElement?.dispatchEvent(new CustomEvent('cart:build', {
        bubbles: true
      }));
      document?.documentElement?.dispatchEvent(new CustomEvent('cart:open', {
        bubbles: true
      }));
    } else if (cart_type === "16") {
      // Baseline theme
      document?.documentElement?.addEventListener('theme:cart:update', () => {
        document?.documentElement?.dispatchEvent(
          new CustomEvent('theme:open:cart-drawer')
        );
      });
      document?.documentElement?.dispatchEvent(
        new CustomEvent('theme:update:cart')
      );
    } else if (cart_type === "17") {
      // Opus Cart app
      window?.opusRefreshCart();
      window?.opusOpen();  
    } else if (cart_type === "18") {
      // Monster Cart app
      if (window?.openCart) {
        await window.openCart();
      } else {
        setTimeout(async () => {
          await window?.openCart?.();
        }, 1000);
      }
    } else if (cart_type === "19") {
      // Impulse theme
      document?.documentElement?.dispatchEvent(new CustomEvent('cart:build', {
        bubbles: true
      }));
      document?.documentElement?.dispatchEvent(new CustomEvent('cart:open', {
        bubbles: true
      }));
    } else if (cart_type === "20") {
      // Envy theme (Eight Themes) - window.eventBus pub/sub
      window?.eventBus?.emit("render:cart:drawer");
      window?.eventBus?.emit("open:cart:drawer");
    } else if (cart_type === "21") {
      // UpCart app (Aftersell) - async public API; refresh then open
      await window?.upcartRefreshCart?.();
      await window?.upcartOpenCart?.();
    }
  }

  const hash = window.location.hash.substring(1);
  const match = hash.match(/(open_cart_drawer=([^&]*))/);
  if (match) {
    const cart_type = match[2];
    const updated_hash = hash.replace(match[1], "");
    window.location.hash = updated_hash ? `#${updated_hash.replace(/^&/, "")}` : "";
    ready(async () => await openCartDrawer(cart_type));
  }
})();
